<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';$user=require_role('admin');
require_once __DIR__.'/../includes/organization_requests.php';$id=donor_donation_id();
require_once __DIR__.'/../includes/admin_workflow.php';
try {
    $query=db()->prepare('SELECT d.*,u.full_name AS donor_name,u.phone AS donor_phone,u.email AS donor_email FROM donations d JOIN users u ON u.id=d.donor_id WHERE d.id=?');$query->execute([$id]);$donation=$query->fetch();
    if (!$donation) {http_response_code(404);exit('Donation not found.');}
    $query=db()->prepare('SELECT r.id,r.status AS request_status,r.created_at,r.decided_at,r.delivery_address,r.message,
        d.status,d.available_at,d.deadline_at,d.completed_at,t.id AS task_id,t.volunteer_id,t.status AS task_status,t.assigned_at,t.accepted_at,t.collected_at,t.delivered_at,
        v.full_name AS volunteer_name,v.phone AS volunteer_phone,o.organization_name,
        recipient.full_name AS recipient_name,recipient.phone AS recipient_phone,recipient.email AS recipient_email
        FROM donation_requests r JOIN donations d ON d.id=r.donation_id JOIN organizations o ON o.id=r.organization_id
        JOIN users recipient ON recipient.id=o.user_id LEFT JOIN collection_tasks t ON t.request_id=r.id
        LEFT JOIN users v ON v.id=t.volunteer_id WHERE r.donation_id=? ORDER BY r.id');
    $query->execute([$id]);$requests=$query->fetchAll();
    $volunteers=db()->query("SELECT id,full_name,email FROM users WHERE role='volunteer' AND status='active' ORDER BY full_name,id")->fetchAll();
} catch (PDOException $exception) {error_log('Admin donation detail failed. Code: '.$exception->getCode());donation_load_error();}
$success=$_SESSION['admin_workflow_success']??null;unset($_SESSION['admin_workflow_success']);
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Donation overview | <?= e(APP_NAME) ?></title><link rel="stylesheet" href="<?= e(app_url('assets/css/bootstrap.min.css')) ?>"><link rel="stylesheet" href="<?= e(app_url('assets/css/style.css')) ?>"></head><body>
<?php $navigationUser=$user;require __DIR__.'/../includes/header.php'; ?><main class="container py-5" id="main-content"><div class="row g-4"><?php $adminPage='donations';require __DIR__.'/../includes/admin_sidebar.php'; ?>
<section class="col-lg-9" aria-labelledby="donation-heading"><div class="dashboard-welcome mb-4"><a class="home-link" href="<?= e(app_url('admin/donations.php')) ?>">&larr; All donations</a><h1 class="h2 mt-3" id="donation-heading"><?= e($donation['food_name']) ?></h1><?= status_badge(donation_display_status($donation)) ?></div>
<section class="account-card mb-4"><h2 class="h5">Food and donor details</h2><p class="donation-description"><?= e($donation['description']) ?></p><dl class="row account-details mb-0"><?php foreach (['Quantity'=>rtrim(rtrim($donation['quantity'],'0'),'.').' '.$donation['quantity_unit'],'Donor'=>$donation['donor_name'],'Donor phone'=>$donation['donor_phone'],'Donor email'=>$donation['donor_email'],'Pickup location'=>$donation['pickup_location'],'Available from'=>dashboard_date($donation['available_at']),'Collect by'=>dashboard_date($donation['deadline_at'])] as $label=>$value): ?><dt class="col-sm-4"><?= e($label) ?></dt><dd class="col-sm-8 donation-description"><?= e($value) ?></dd><?php endforeach; ?></dl></section>
<?php if (is_array($success) && ($success['id']??null)===$id): ?><div class="alert alert-success" role="status"><?= e($success['message']) ?></div><?php endif; ?>
<?php if (admin_can_cancel_food($donation,$requests)): ?><section class="account-card mb-4"><h2 class="h5">Cancel donation</h2><p>Cancel before food is collected. Open requests and assigned or accepted tasks will be closed together. This cannot be undone.</p><form method="post" action="<?= e(app_url('admin/cancel_donation.php?id='.$id)) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-check mb-3"><input class="form-check-input" id="confirm-cancel" name="confirm_cancel" value="yes" type="checkbox" required><label class="form-check-label" for="confirm-cancel">I confirm cancellation of this donation and its open requests and tasks.</label></div><button class="btn btn-outline-danger">Cancel donation</button></form></section><?php endif; ?>
<h2 class="h4 mb-3">Requests and collection progress</h2><?php if (!$requests): ?><div class="account-card">No organization has requested this donation.</div><?php endif; ?>
<?php foreach ($requests as $request): ?><section class="account-card mb-4" id="request-<?= e((string)$request['id']) ?>"><h3 class="h5"><?= e($request['organization_name']) ?></h3><p>Request: <?= status_badge($request['request_status']) ?><?php if ($request['task_status']!==null): ?> &middot; Task: <?= status_badge($request['task_status']) ?><?php endif; ?></p><dl class="row account-details"><?php foreach (['Contact person'=>$request['recipient_name'],'Organization phone'=>$request['recipient_phone'],'Organization email'=>$request['recipient_email'],'Delivery address'=>$request['delivery_address'],'Request message'=>$request['message']??'No message provided.','Volunteer'=>$request['volunteer_name']??'Not assigned','Volunteer phone'=>$request['volunteer_phone']??'Not assigned'] as $label=>$value): ?><dt class="col-sm-4"><?= e($label) ?></dt><dd class="col-sm-8 donation-description"><?= e($value) ?></dd><?php endforeach; ?></dl>
<?php if ($request['request_status']==='approved'): ?><ol class="request-timeline"><?php foreach (organization_tracking_steps($request) as [$label,$time]): ?><li class="<?= $time!==null?'is-recorded':'' ?>"><span class="timeline-dot" aria-hidden="true"></span><div><strong><?= e($label) ?></strong><span><?= $time!==null?e(dashboard_date($time)):'Not recorded yet' ?></span></div></li><?php endforeach; ?></ol><?php if ($request['accepted_at']!==null): ?><p class="form-text mt-3">Task accepted: <?= e(dashboard_date($request['accepted_at'])) ?></p><?php endif; ?>
<?php if ($request['task_id']===null && donation_display_status($donation)==='requested'): ?><a class="btn btn-community mt-3" href="<?= e(app_url('admin/assignments.php')) ?>">Assign a volunteer &rarr;</a><?php endif; ?>
<?php if ($request['task_id']!==null && volunteer_next_action($request)==='accept'): ?><form method="post" action="<?= e(app_url('admin/reassign_volunteer.php?id='.$request['task_id'])) ?>" class="mt-4"><h4 class="h6">Reassign volunteer before acceptance</h4><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="current_volunteer_id" value="<?= e((string)$request['volunteer_id']) ?>"><label class="form-label" for="replacement-<?= e((string)$request['task_id']) ?>">Replacement volunteer</label><select class="form-select mb-3" name="volunteer_id" id="replacement-<?= e((string)$request['task_id']) ?>" required><option value="">Choose a different volunteer</option><?php foreach ($volunteers as $volunteer): ?><?php if ((int)$volunteer['id']!==(int)$request['volunteer_id']): ?><option value="<?= e((string)$volunteer['id']) ?>"><?= e($volunteer['full_name'].' — '.$volunteer['email']) ?></option><?php endif; ?><?php endforeach; ?></select><div class="form-check mb-3"><input class="form-check-input" id="confirm-reassign-<?= e((string)$request['task_id']) ?>" name="confirm_reassign" value="yes" type="checkbox" required><label class="form-check-label" for="confirm-reassign-<?= e((string)$request['task_id']) ?>">I confirm this change of volunteer.</label></div><button class="btn btn-community">Reassign volunteer</button></form><?php endif; ?>
<?php else: ?><p class="form-text mb-0">Submitted <?= e(dashboard_date($request['created_at'])) ?>. <?= $request['decided_at']!==null?'Decision recorded '.e(dashboard_date($request['decided_at'])).'.':'Awaiting donor review.' ?></p><?php endif; ?></section><?php endforeach; ?>
</section></div></main><?php require __DIR__.'/../includes/footer.php'; ?></body></html>
